 #include <torch/extension.h>
 #include <ATen/cuda/CUDAContext.h>
 #include <cuda.h>
 #include <cuda_runtime.h>
 #include <algorithm>

 template<int BLOCK_SIZE, bool VEC4>
 __global__ void triplet_margin_partial_kernel(const float* __restrict__ anchor,
                                              const float* __restrict__ positive,
                                              const float* __restrict__ negative,
                                              float* __restrict__ sum_pos,
                                              float* __restrict__ sum_neg,
                                              int64_t B,
                                              int64_t D) {
     extern __shared__ float shared[];
     const int WARPS = (BLOCK_SIZE + 31) / 32;
     float* s1 = shared;                  // partial sums for positive distance (per-warp)
     float* s2 = shared + WARPS;          // partial sums for negative distance (per-warp)
     unsigned int mask = 0xffffffffu;
     int lane = threadIdx.x & 31;
     int wid  = threadIdx.x >> 5;  // warp id within the block

     for (int64_t i = blockIdx.x; i < B; i += gridDim.x) {
         float sum1 = 0.0f;
         float sum2 = 0.0f;
         int64_t base = static_cast<int64_t>(i) * D;

         if (VEC4) {
             // Vectorized path with D partitioned across gridDim.y
             int64_t vecD = D >> 2; // number of float4 elements
             int64_t start4 = (vecD * static_cast<int64_t>(blockIdx.y)) / static_cast<int64_t>(gridDim.y);
             int64_t end4   = (vecD * (static_cast<int64_t>(blockIdx.y) + 1)) / static_cast<int64_t>(gridDim.y);
             const float4* __restrict__ a4 = reinterpret_cast<const float4*>(anchor + base);
             const float4* __restrict__ p4 = reinterpret_cast<const float4*>(positive + base);
             const float4* __restrict__ n4 = reinterpret_cast<const float4*>(negative + base);
             for (int64_t j4 = start4 + threadIdx.x; j4 < end4; j4 += BLOCK_SIZE * 4) {
                 #pragma unroll
                 for (int ui = 0; ui < 4; ++ui) {
                     int64_t idx = j4 + static_cast<int64_t>(ui) * BLOCK_SIZE;
                     if (idx < end4) {
                         float4 av = a4[idx];
                         float4 pv = p4[idx];
                         float4 nv = n4[idx];
                         float dpx = av.x - pv.x; float dnx = av.x - nv.x;
                         float dpy = av.y - pv.y; float dny = av.y - nv.y;
                         float dpz = av.z - pv.z; float dnz = av.z - nv.z;
                         float dpw = av.w - pv.w; float dnw = av.w - nv.w;
                         sum1 += dpx*dpx + dpy*dpy + dpz*dpz + dpw*dpw;
                         sum2 += dnx*dnx + dny*dny + dnz*dnz + dnw*dnw;
                     }
                 }
             }
         } else {
             // Scalar path with D partitioned across gridDim.y
             int64_t start = (D * static_cast<int64_t>(blockIdx.y)) / static_cast<int64_t>(gridDim.y);
             int64_t end   = (D * (static_cast<int64_t>(blockIdx.y) + 1)) / static_cast<int64_t>(gridDim.y);
             for (int64_t j = start + threadIdx.x; j < end; j += BLOCK_SIZE * 4) {
                 #pragma unroll
                 for (int ui = 0; ui < 4; ++ui) {
                     int64_t idx = j + static_cast<int64_t>(ui) * BLOCK_SIZE;
                     if (idx < end) {
                         float a = anchor[base + idx];
                         float p = positive[base + idx];
                         float n = negative[base + idx];
                         float dp = a - p;
                         float dn = a - n;
                         sum1 += dp * dp;
                         sum2 += dn * dn;
                     }
                 }
             }
         }

         // Warp-level reduction
         #pragma unroll
         for (int offset = 16; offset > 0; offset >>= 1) {
             sum1 += __shfl_down_sync(mask, sum1, offset);
             sum2 += __shfl_down_sync(mask, sum2, offset);
         }
         if (lane == 0) {
             s1[wid] = sum1;
             s2[wid] = sum2;
         }
         __syncthreads();

         float block_sum1 = 0.0f;
         float block_sum2 = 0.0f;
         if (wid == 0) {
             if (lane < WARPS) {
                 block_sum1 = s1[lane];
                 block_sum2 = s2[lane];
             }
             #pragma unroll
             for (int offset = 16; offset > 0; offset >>= 1) {
                 block_sum1 += __shfl_down_sync(mask, block_sum1, offset);
                 block_sum2 += __shfl_down_sync(mask, block_sum2, offset);
             }
             if (lane == 0) {
                 // Accumulate partial sums for this sample over D-tiles
                 atomicAdd(&sum_pos[i], block_sum1);
                 atomicAdd(&sum_neg[i], block_sum2);
             }
         }
         __syncthreads();
     }
 }

 template<int BLOCK_SIZE>
 __global__ void triplet_finalize_kernel(const float* __restrict__ sum_pos,
                                         const float* __restrict__ sum_neg,
                                         float* __restrict__ out,
                                         int64_t B,
                                         float margin,
                                         float eps) {
     for (int64_t i = static_cast<int64_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
          i < B;
          i += static_cast<int64_t>(gridDim.x) * BLOCK_SIZE) {
         float dpos = sqrtf(sum_pos[i] + eps);
         float dneg = sqrtf(sum_neg[i] + eps);
         float l = dpos - dneg + margin;
         if (l < 0.0f) l = 0.0f;
         out[i] = l;
     }
 }

 template<int BLOCK_SIZE>
 __global__ void reduce_mean_kernel(const float* __restrict__ in,
                                    float* __restrict__ out,
                                    int64_t B) {
     extern __shared__ float shared[];
     const int WARPS = (BLOCK_SIZE + 31) / 32;
     float sum = 0.0f;
     // grid-stride loop with unrolling
     for (int64_t idx = static_cast<int64_t>(blockIdx.x) * BLOCK_SIZE * 4 + threadIdx.x;
          idx < B;
          idx += static_cast<int64_t>(gridDim.x) * BLOCK_SIZE * 4) {
         #pragma unroll
         for (int ui = 0; ui < 4; ++ui) {
             int64_t i2 = idx + static_cast<int64_t>(ui) * BLOCK_SIZE;
             if (i2 < B) {
                 sum += in[i2];
             }
         }
     }
     unsigned int mask = 0xffffffffu;
     int lane = threadIdx.x & 31;
     int wid  = threadIdx.x >> 5;
     #pragma unroll
     for (int offset = 16; offset > 0; offset >>= 1) {
         sum += __shfl_down_sync(mask, sum, offset);
     }
     if (lane == 0) {
         shared[wid] = sum;
     }
     __syncthreads();
     float block_sum = 0.0f;
     if (wid == 0) {
         if (lane < WARPS) {
             block_sum = shared[lane];
         }
         #pragma unroll
         for (int offset = 16; offset > 0; offset >>= 1) {
             block_sum += __shfl_down_sync(mask, block_sum, offset);
         }
         if (lane == 0) {
             atomicAdd(out, block_sum / static_cast<float>(B));
         }
     }
 }

 torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                        torch::Tensor positive,
                                        torch::Tensor negative,
                                        double margin,
                                        double eps) {
     TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
     TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
     TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");
     TORCH_CHECK(anchor.scalar_type() == at::ScalarType::Float, "Only float32 supported for anchor");
     TORCH_CHECK(positive.scalar_type() == at::ScalarType::Float, "Only float32 supported for positive");
     TORCH_CHECK(negative.scalar_type() == at::ScalarType::Float, "Only float32 supported for negative");
     TORCH_CHECK(anchor.numel() > 0, "Empty anchor tensor");
     TORCH_CHECK(anchor.sizes() == positive.sizes(), "anchor and positive must have the same shape");
     TORCH_CHECK(anchor.sizes() == negative.sizes(), "anchor and negative must have the same shape");
     TORCH_CHECK(anchor.size(0) >= 1, "Expected shape [B, ...] with B >= 1");

     auto a = anchor.contiguous().view({anchor.size(0), -1});
     auto p = positive.contiguous().view({positive.size(0), -1});
     auto n = negative.contiguous().view({negative.size(0), -1});
     const int64_t B = a.size(0);
     const int64_t D = a.size(1);

     // Per-sample output buffer and intermediate partial sums
     auto out_vec = torch::empty({B}, a.options());
     auto sum_pos = torch::zeros({B}, a.options());
     auto sum_neg = torch::zeros({B}, a.options());

     constexpr int BLOCK = 256;
     dim3 block(BLOCK);

     // Choose a 2D grid to increase parallelism across both batch and feature dimensions
     int sm_count = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
     int64_t grid_x = std::min<int64_t>(B, static_cast<int64_t>(sm_count) * 8);
     // Partition D across Y dimension (tile size ~4096 elements, capped to avoid overly large grids)
     int64_t tiles_y = std::min<int64_t>(std::max<int64_t>(1, (D + 4095) / 4096), 64LL);
     dim3 grid(static_cast<unsigned int>(grid_x), static_cast<unsigned int>(tiles_y), 1u);

     size_t shmem = 2 * ((BLOCK + 31) / 32) * sizeof(float);
     if ((D & 3LL) == 0) {
         triplet_margin_partial_kernel<BLOCK, true><<<grid, block, shmem, at::cuda::getCurrentCUDAStream()>>>(
             a.data_ptr<float>(),
             p.data_ptr<float>(),
             n.data_ptr<float>(),
             sum_pos.data_ptr<float>(),
             sum_neg.data_ptr<float>(),
             B,
             D
         );
     } else {
         triplet_margin_partial_kernel<BLOCK, false><<<grid, block, shmem, at::cuda::getCurrentCUDAStream()>>>(
             a.data_ptr<float>(),
             p.data_ptr<float>(),
             n.data_ptr<float>(),
             sum_pos.data_ptr<float>(),
             sum_neg.data_ptr<float>(),
             B,
             D
         );
     }
     auto err = cudaGetLastError();
     TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed (partial): ", cudaGetErrorString(err));

     // Finalize per-sample losses from accumulated squared distances
     constexpr int BLOCK_F = 256;
     int64_t blocksF = std::min<int64_t>((B + BLOCK_F - 1) / BLOCK_F, 4096LL);
     if (blocksF < 1) blocksF = 1;
     triplet_finalize_kernel<BLOCK_F><<<static_cast<unsigned int>(blocksF), BLOCK_F, 0, at::cuda::getCurrentCUDAStream()>>>(
         sum_pos.data_ptr<float>(),
         sum_neg.data_ptr<float>(),
         out_vec.data_ptr<float>(),
         B,
         static_cast<float>(margin),
         static_cast<float>(eps)
     );
     err = cudaGetLastError();
     TORCH_CHECK(err == cudaSuccess, "CUDA finalize kernel launch failed: ", cudaGetErrorString(err));

     // Now reduce per-sample losses to mean
     auto out = torch::zeros({}, a.options());
     constexpr int BLOCK_R = 256;
     int64_t blocksR = std::min<int64_t>((B + (BLOCK_R * 4 - 1)) / (BLOCK_R * 4), 4096LL);
     if (blocksR < 1) blocksR = 1;
     size_t shmemR = ((BLOCK_R + 31) / 32) * sizeof(float);
     reduce_mean_kernel<BLOCK_R><<<static_cast<unsigned int>(blocksR), BLOCK_R, shmemR, at::cuda::getCurrentCUDAStream()>>>(
         out_vec.data_ptr<float>(),
         out.data_ptr<float>(),
         B
     );
     err = cudaGetLastError();
     TORCH_CHECK(err == cudaSuccess, "CUDA reduction kernel launch failed: ", cudaGetErrorString(err));
     return out;
 }
