class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks using a single fused CUDA kernel.
    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.eps = 1e-6
    def forward(self, anchor, positive, negative):
        # Move inputs to CUDA and ensure dtype/contiguity
        orig_device = anchor.device
        # Ensure same device
        if not anchor.is_cuda or not positive.is_cuda or not negative.is_cuda:
            anchor = anchor.to('cuda', dtype=torch.float32, non_blocking=False)
            positive = positive.to('cuda', dtype=torch.float32, non_blocking=False)
            negative = negative.to('cuda', dtype=torch.float32, non_blocking=False)
        else:
            anchor = anchor.contiguous().to(dtype=torch.float32)
            positive = positive.contiguous().to(dtype=torch.float32)
            negative = negative.contiguous().to(dtype=torch.float32)
        # Shape and size checks are done in the CUDA function as well
        out = _triplet_loss_ext.triplet_margin_loss_cuda(anchor, positive, negative, self.margin, self.eps)
        # Return result on the original device of anchor for compatibility
        if orig_device.type != 'cuda':
            out = out.to(orig_device)
        return out
